//! WAV format constructor, generated by [`impl_audio_handler!`].
//!
//! [`impl_audio_handler!`]: super::macros::impl_audio_handler

use super::macros::impl_audio_handler;

impl_audio_handler! {
    format_id = "elide.audio.wav",
    audio_format = crate::modality::AudioFormat::Wav,
    extensions = ["wav"],
    content_types = ["audio/wav", "audio/x-wav"],
}

#[cfg(test)]
mod tests {
    use elide_codec::content::ContentData;
    use elide_codec::{Document, DocumentPart, Stripped};
    use elide_core::Result;
    use elide_core::modality::ChunkReader as _;
    use elide_core::redaction::{Disposition, HiddenContent, HiddenContentPolicy};

    use super::*;
    use crate::fixtures;
    use crate::modality::Audio;

    /// Decode `bytes` as WAV under a policy applying `metadata`.
    async fn decode(bytes: impl Into<ContentData>, metadata: Disposition) -> Result<Document> {
        let policy = HiddenContentPolicy::default().with_metadata(metadata);
        format().decode(bytes.into(), policy).await
    }

    /// `bytes` with a `LIST/INFO` chunk naming an artist appended.
    fn with_artist(bytes: &[u8]) -> Vec<u8> {
        let mut out = bytes.to_vec();
        out.extend_from_slice(b"LIST\x12\x00\x00\x00INFOIART\x06\x00\x00\x00Jane R");
        let riff_size = (out.len() - 8) as u32;
        out[4..8].copy_from_slice(&riff_size.to_le_bytes());
        out
    }

    fn contains(haystack: &[u8], needle: &[u8]) -> bool {
        haystack.windows(needle.len()).any(|w| w == needle)
    }

    #[tokio::test]
    async fn stream_reports_one_second() {
        let mut doc = decode(fixtures::wav_ramp(1), Disposition::KeepOnlyEssential)
            .await
            .expect("decode");
        let DocumentPart::Stream { handle, .. } = &mut doc.parts_mut()[0] else {
            panic!("a clip is one stream")
        };
        let chunks = handle.downcast_mut::<Audio>().unwrap().chunks().unwrap();
        assert_eq!(chunks.len(), 1);
        assert_eq!(chunks[0].location.span.start_millis(), 0);
        assert_eq!(chunks[0].location.span.end_millis(), 1_000);
    }

    #[tokio::test]
    async fn strip_removes_the_info_chunk_at_decode() {
        let doc = decode(
            with_artist(&fixtures::wav_ramp(1)),
            Disposition::KeepOnlyEssential,
        )
        .await
        .expect("decode");
        let stripped: Vec<Stripped> = doc.stripped().iter().collect();
        assert_eq!(
            stripped,
            [Stripped {
                content: HiddenContent::Properties,
                at: None,
                count: 1,
            }]
        );
        let out = doc.encode().expect("encode");
        assert!(!contains(out.as_bytes(), b"Jane R"));
    }

    #[tokio::test]
    async fn redact_strips_the_info_chunk_it_cannot_surface() {
        let doc = decode(
            with_artist(&fixtures::wav_ramp(1)),
            Disposition::ScanAsContent,
        )
        .await
        .expect("decode");
        assert!(doc.changed_at_decode());
        let out = doc.encode().expect("encode");
        assert!(!contains(out.as_bytes(), b"Jane R"));
    }

    /// The WAV loader rejects content that opens as another format.
    #[cfg(feature = "mp3")]
    #[tokio::test]
    async fn loader_rejects_content_of_another_format() {
        let err = decode(fixtures::mp3_tone(1), Disposition::KeepOnlyEssential)
            .await
            .expect_err("mp3 content should not decode as wav");
        assert_eq!(err.kind(), elide_core::ErrorKind::MalformedInput);
    }
}
